from pathlib import Path
import json,shutil
b=Path('Library/WorkshopBackups/DB-ON-100');b.mkdir(parents=True,exist_ok=True)
for src,name in [('Assets/Scenes/LobbyIslandWorkshop.unity','LobbyIslandWorkshop.before.unity'),('Assets/Scenes/CastleServicesWorkshop.unity','CastleServicesWorkshop.before.unity'),('Assets/Igrodelnya/Localization/LocalizationData.asset','LocalizationData.before.asset')]:shutil.copy2(src,b/name)
code=r'''using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;public static class Inspect100{public static string Run(){var b=new StringBuilder();foreach(var f in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Workshop/GameAligned"}).Select(AssetDatabase.GUIDToAssetPath))b.AppendLine("BOAT "+f);foreach(var q in new[]{"chest","bed","chair","shelf","cabinet"})foreach(var f in AssetDatabase.FindAssets(q).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.EndsWith(".prefab")||p.EndsWith(".fbx")).Take(15))b.AppendLine("PROP "+f);foreach(var path in new[]{"Assets/Prefabs/Gem.prefab","Assets/Prefabs/Items/Pistol.prefab","Assets/Prefabs/Items/Shotgun.prefab","Assets/Prefabs/Items/Rifle.prefab","Assets/Prefabs/Items/Lantern.prefab","Assets/Prefabs/Items/Fence.prefab"}){var a=AssetDatabase.LoadAssetAtPath<GameObject>(path);foreach(var r in a.GetComponentsInChildren<MeshRenderer>(true))b.AppendLine(path+" mesh="+r.name+" mat="+string.Join(",",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)))+" shader="+r.sharedMaterial.shader.name);}System.IO.File.WriteAllText("Library/WorkshopBackups/DB-ON-100/inspect.txt",b.ToString());return b.ToString();}}'''
(b/'inspect.json').write_text(json.dumps({'csharpCode':code,'className':'Inspect100','methodName':'Run'}),encoding='utf-8')
